    WHERE m.entity_type = 'product' AND m.entity_id = p.id AND m.storage_key = 'products/mini-pouch-old-hong-kong.jpg'
  );

INSERT INTO media (storage_key, alt, is_primary, created_at, entity_type, entity_id)
SELECT 'products/mini-pouch-canada.jpg', 'Mini Pouch Canada', TRUE, now(), 'product', p.id
FROM product p
WHERE p.slug = 'mini-pouch-canada'
  AND NOT EXISTS (
    SELECT 1 FROM media m
    WHERE m.entity_type = 'product' AND m.entity_id = p.id AND m.storage_key = 'products/mini-pouch-canada.jpg'
  );

-- Link primary media to product.image_media_id
UPDATE product
SET image_media_id = m.id
FROM media m
WHERE m.entity_type = 'product'
  AND m.entity_id = product.id
  AND m.is_primary = TRUE;

